INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(51411, 'Ezekiel 20:12', 'Ezekiel', 20, 12, 'برسېره پردې هغوی ته مې حکم وکړ چې زما د سبت د ورځې درناوی وکړي چې دا به زمونږ ترمنځ د لوظ نښه وي او هغوی ته دا ور په یاد کړي چې ما څښتن هغوی سپېڅلي کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_12.mp3', '', 1761754199, 1761754199),
(51412, 'Ezekiel 20:13', 'Ezekiel', 20, 13, 'خو د اسراییلو قوم په دښته کې هم زما په وړاندې سرکښي وکړه. د اسراییلو قوم زما د قوانینو څخه اطاعت نه دی کړی او زما حکمونه یې رد کړي دي، نو هرڅوک چې ورباندې عمل وکړي، هغوی به ژوندي پاتې شي. د اسراییلو قوم په پوره توګه زما د سبت د ورځې بې ‌عزتي وکړه. نو ما وویل چې زه به په دښته کې اسراییلو ته خپل قهر وښایم او هغوی به ووژنم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_13.mp3', '', 1761754199, 1761754199),
(51413, 'Ezekiel 20:14', 'Ezekiel', 20, 14, 'خو ما دا کار ونه کړ، ترڅو د هغو قومونو په مخکې چې زه یې لیدلی وم چې اسراییلیان مې د مصر نه راوویستل، زما نوم سپک نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_14.mp3', '', 1761754199, 1761754199),
(51414, 'Ezekiel 20:15', 'Ezekiel', 20, 15, 'نو برسېره پردې ما په دښته کې قسم وخوړ چې د اسراییلو قوم به هغه وطن ته چې هغوی ته مې ورکړی ؤ او هغه یو غني، حاصلخېزه او د ټولو نه ښه وطن دی، بو نه ځم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_15.mp3', '', 1761754199, 1761754199),
(51415, 'Ezekiel 20:16', 'Ezekiel', 20, 16, 'ما داسې وویل چې هغوی زما حکمونه رد کړل، زما د قوانینو څخه یې اطاعت نه کاوه او د سبت د ورځې بې‌عزتي یې وکړه، ځکه هغوی خپل زړونه خپلو بتانو ته ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_16.mp3', '', 1761754199, 1761754199),
(51416, 'Ezekiel 20:17', 'Ezekiel', 20, 17, 'خو بیا مې په هغوی باندې رحم وکړ. ما پرېکړه وکړه چې هغوی به په دښته کې ونه وژنم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_17.mp3', '', 1761754199, 1761754199),
(51417, 'Ezekiel 20:18', 'Ezekiel', 20, 18, 'خو د هغې په ځای مې د هغوی اولادونو ته په دښته کې وویل چې د خپلو نیکونو په قوانینو او حکمونو باندې عمل مه کوئ او خپل ځانونه د هغوی په بتانو باندې مه ناپاکه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_18.mp3', '', 1761754199, 1761754199),
(51418, 'Ezekiel 20:19', 'Ezekiel', 20, 19, 'زه ستاسو څښتن خدای یم. زما د قوانینو نه پیروي وکړئ او په غور سره زما په حکمونو باندې عمل وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_19.mp3', '', 1761754199, 1761754199),
(51419, 'Ezekiel 20:20', 'Ezekiel', 20, 20, 'د سبت ورځ سپېڅلې وګڼئ، ترڅو دا د هغه لوظ نښه وي چې زمونږ ترمنځ شوی دی او بیا به تاسو پوه شئ چې زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_20.mp3', '', 1761754199, 1761754199),
(51420, 'Ezekiel 20:21', 'Ezekiel', 20, 21, 'خو د اسراییلو اولادونو هم زما په وړاندې سرکښي وکړه. هغوی زما د قوانینو څخه اطاعت ونه کړ او زما په حکمونو باندې یې په غور سره عمل ونه کړ، که هرڅوک په هغه باندې عمل وکړي، نو ژوندی به پاتې شي. هغوی زما د سبت د ورځې بې‌عزتي وکړه. نو زه دې ته تیار وم چې په دښته کې په هغوی باندې خپل غضب نازل کړم او خپل قهر به ورباندې سوړ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_21.mp3', '', 1761754199, 1761754199),
(51421, 'Ezekiel 20:22', 'Ezekiel', 20, 22, 'خو ما دا کار ونه کړ، ترڅو د هغو قومونو په مخکې چې زه یې لیدلی وم چې اسراییلیان مې د مصر نه راوویستل، زما نوم سپک نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_22.mp3', '', 1761754199, 1761754199),
(51422, 'Ezekiel 20:23', 'Ezekiel', 20, 23, 'نو په هغې دښتې کې مې یو بل قسم وخوړ چې هغوی به په نورو قومونو او وطنونو کې خواره واره کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_23.mp3', '', 1761754199, 1761754199),
(51423, 'Ezekiel 20:24', 'Ezekiel', 20, 24, 'دا کار ما ځکه وکړ چې هغوی زما حکمونه ونه منل، زما قوانین یې مات کړل، د سبت د ورځې بې‌عزتي یې وکړه او د هماغو بتانو عبادت یې کاوه چې نیکونو یې هم کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_24.mp3', '', 1761754199, 1761754199),
(51424, 'Ezekiel 20:25', 'Ezekiel', 20, 25, 'برسېره پردې هغوی ته مې داسې قوانین ورکړل چې ښه نه وو او داسې حکمونه مې ورته ورکړل چې ژوند بخښونکي نه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_25.mp3', '', 1761754199, 1761754199),
(51425, 'Ezekiel 20:26', 'Ezekiel', 20, 26, 'ما هغوی په هغو سوغاتونو باندې چې ماته یې راکړي دي، ناپاکه کړل، کله چې هغوی خپل لومړني زېږول شوي اولادونه خپلو خدایانو ته د نذرانو په توګه وړاندې کړل. نو ما داسې وکړل چې هغوی برباد کړم، ترڅو هغوی په دې پوه شي چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_26.mp3', '', 1761754199, 1761754199),
(51426, 'Ezekiel 20:27', 'Ezekiel', 20, 27, 'نو ای فاني انسانه، اسراییلیانو ته ووایه چې زه څښتن تعالی داسې وایم: ‹ستاسو نیکونو په بله طریقه هم په بې‌وفایۍ سره زما سپکاوی وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_27.mp3', '', 1761754199, 1761754199),
(51427, 'Ezekiel 20:28', 'Ezekiel', 20, 28, 'ما هغوی هغه وطن ته راوستل چې د هغوی سره مې قسم کړی ؤ. نو کله چې هغوی لوړې غونډۍ او شنې ونې ولیدلې، نو هغوی هلته خپلې قربانۍ وړاندې کړلې. هغوی د قربانیو د سوځولو په خوشبویۍ او څښلو د نذرانو په راوړلو سره زه په قهر کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_28.mp3', '', 1761754199, 1761754199),
(51428, 'Ezekiel 20:29', 'Ezekiel', 20, 29, 'ما د هغوی نه پوښتنه وکړه: ”دا لوړ لوړ د عبادت ځایونه چې تاسو ورته ورځئ، هغه څه دي؟“ نو هغه ځایونه تر نن ورځې پورې د «بامه» یعنې لوړ د عبادت ځای په نوم یادیږي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_29.mp3', '', 1761754199, 1761754199),
(51429, 'Ezekiel 20:30', 'Ezekiel', 20, 30, 'نو له دې امله اسراییلیانو ته ووایه چې څښتن تعالی داسې وایي: ‹تاسو ولې په هماغو ګناهونو باندې خپل ځانونه ناپاکه کوئ چې ستاسو نیکونو کړي وو او د هغوی د کرکې وړ بتانو پسې منډې وهئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_30.mp3', '', 1761754199, 1761754199),
(51430, 'Ezekiel 20:31', 'Ezekiel', 20, 31, 'حتی اوس هم تاسو هماغه سوغاتونه وړاندې کوئ، هماغو بتانو ته خپل اولادونه په اور کې قرباني کوئ او خپل ځانونه په هغو بتانو باندې ناپاکه کوئ. بیاهم تاسو اسراییلیان راځئ او پوښتنه کوئ چې زما رضا څه ده! زه څښتن تعالی په خپل ذات باندې قسم خورم چې زه به تاسو پرېنږدم چې زما څخه د کوم شي په هکله پوښتنه وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_31.mp3', '', 1761754199, 1761754199),
(51431, 'Ezekiel 20:32', 'Ezekiel', 20, 32, 'تاسو پرېکړه کړې ده چې د هغو نورو قومونو په شان شئ چې په نورو وطنونو کې اوسیږي او د لرګیو او تیږو نه جوړ شویو بتانو ته عبادت کوي. خو هېڅکله به ستاسو دا پرېکړه عملي نه شي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_32.mp3', '', 1761754199, 1761754199),
(51432, 'Ezekiel 20:33', 'Ezekiel', 20, 33, '«زه څښتن تعالی په خپل ذات باندې قسم خورم چې زه به په خپل قهر او قوي مټو او ټول قدرت سره په تاسو باندې پاچاهي وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_33.mp3', '', 1761754199, 1761754199),
(51433, 'Ezekiel 20:34', 'Ezekiel', 20, 34, 'زه به تاسو په خپل قوي مټ، ټول قدرت او سخت قهر سره د هغو وطنونو نه چې په کې خواره واره یئ، بېرته راولم او سره راټول به مو کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_34.mp3', '', 1761754199, 1761754199),
(51434, 'Ezekiel 20:35', 'Ezekiel', 20, 35, 'زه به تاسو «د قومونو دښتې» ته راولم، هلته به درسره مخامخ شم او تاسو به محاکمه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_35.mp3', '', 1761754199, 1761754199),
(51435, 'Ezekiel 20:36', 'Ezekiel', 20, 36, 'څښتن تعالی داسې وایي زه به هماغه شان تاسو محاکمه کړم لکه څنګه چې مې ستاسو نیکونه د مصر سره نژدې په دښته کې محاکمه کړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_36.mp3', '', 1761754199, 1761754199),
(51436, 'Ezekiel 20:37', 'Ezekiel', 20, 37, 'تاسو به مجبور کړم چې زما په لوظ باندې عمل وکړئ. زه به تاسو یو له بل نه داسې بېل کړم لکه څنګه چې شپون په خپل کوتک سره ښه او بد پسونه بېلوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_37.mp3', '', 1761754199, 1761754199),
(51437, 'Ezekiel 20:38', 'Ezekiel', 20, 38, 'زه به ستاسو له منځ نه سرکښه او ګناهکار خلک لېرې کړم او هغوی به له هغو وطنونو نه چې اوس په کې اوسیږي وباسم، خو هغوی به پرېنږدم چې د اسراییلو هېواد ته بېرته ورستانه شي. بیا به تاسو پوه شئ چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_38.mp3', '', 1761754199, 1761754199),
(51438, 'Ezekiel 20:39', 'Ezekiel', 20, 39, 'څښتن تعالی داسې وویل: ‹ای اسراییلیانو، اوس هر څه چې غواړئ هغه وکړئ، نو لاړ شئ او د خپلو بتانو خدمت وکړئ! خو زه تاسو ته خبرداری درکوم چې له دې وروسته به زما پیروي کوئ او خپلو بتانو ته د سوغاتونو په ورکولو سره زما د سپېڅلي نوم سپکاوی بس کړئ.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_39.mp3', '', 1761754199, 1761754199),
(51439, 'Ezekiel 20:40', 'Ezekiel', 20, 40, 'څښتن تعالی داسې وایي: ‹زما په سپېڅلي غره باندې یعنې د اسراییلو په اوچت غره باندې به تاسو ټول اسراییلیان زما عبادت کوئ. زه به هلته تاسو قبول کړم چې ماته اعانې، ډېر ښه سوغاتونه او خپلې سپېڅلې نذرانې راوړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_40.mp3', '', 1761754199, 1761754199),
(51440, 'Ezekiel 20:41', 'Ezekiel', 20, 41, 'کله چې ما تاسو د هغو وطنونو نه چې په کې خپاره یئ راولم او تاسو سره راټول کړم، نو زه به تاسو قبول کړم، لکه څنګه چې د سوځېدونکو نذرانو خوشبویي قبلوم. نو ټول قومونه به وویني چې زه سپېڅلی یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_41.mp3', '', 1761754199, 1761754199),
(51441, 'Ezekiel 20:42', 'Ezekiel', 20, 42, 'کله چې زه تاسو د اسراییلو هېواد ته چې ستاسو نیکونو سره مې قسم کړی ؤ، بېرته راولم، نو بیا به تاسو پوه شئ چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_42.mp3', '', 1761754199, 1761754199),
(51442, 'Ezekiel 20:43', 'Ezekiel', 20, 43, 'بیا به تاسو ته هغه شرموونکي کارونه چې تاسو کړي دي او خپل ځانونه مو ورباندې ناپاکه کړي دي، در په یاد شي. تاسو به د خپلو بدو کارونو په سبب له خپلو ځانونو نه بېزاره شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_43.mp3', '', 1761754199, 1761754199),
(51443, 'Ezekiel 20:44', 'Ezekiel', 20, 44, 'کله چې زه ستاسو سره د خپل نوم په خاطر نرم چلند وکړم، نو بیا به تاسو پوه شئ چې زه څښتن یم، ځکه چې زه ستاسو د بدو عملونو او فاسدو کارونو له مخې چې تاسو یې لایق یئ، معامله نه کوم. څښتن تعالی داسې ویلي دي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_44.mp3', '', 1761754199, 1761754199),
(51444, 'Ezekiel 20:45', 'Ezekiel', 20, 45, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_45.mp3', '', 1761754199, 1761754199),
(51445, 'Ezekiel 20:46', 'Ezekiel', 20, 46, '«ای فاني انسانه، خپل مخ د جنوب خواته واړوه او د هغه په ضد خبرې وکړه او د جنوب خوا د ځنګلونو په ضد نبوت وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_46.mp3', '', 1761754199, 1761754199),
(51446, 'Ezekiel 20:47', 'Ezekiel', 20, 47, 'د جنوبي خوا ځنګلونو ته ووایه چې څښتن تعالی چې څه وایي هغو ته غوږ ونیسه: ‹ګوره، زه به اوس اور بل کړم او دا اور به ستا ټولې ونې وسوځوي که هغه شنې وي یا وچې وي. هېڅ شی به دا اور نه شي مړ کولای. هغه به د جنوب نه تر شماله پورې خپور شي او هرچا ته به د هغه لمبې ورورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_47.mp3', '', 1761754199, 1761754199),
(51447, 'Ezekiel 20:48', 'Ezekiel', 20, 48, 'بیا به ټول خلک پوه شي چې دا اور ما څښتن لګولی دی او هېڅوک یې نه شي مړ کولای.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_48.mp3', '', 1761754199, 1761754199),
(51448, 'Ezekiel 20:49', 'Ezekiel', 20, 49, 'خو ما ګیله وکړه: «ای څښتن تعالی، ما مه مجبوروه چې دا کار وکړم! هغوی لا د مخکې نه دا شکایت کوي چې زه تل هغوی ته معماګانې وایم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel20_verse_49.mp3', '', 1761754199, 1761754199),
(51449, 'Genesis 9:1', 'Genesis', 9, 1, 'خدای نوح او د هغه زامنو ته برکت ورکړ او ویې ویل: «ستاسو اولادونه دې زیات شي، ترڅو ټوله نړۍ ستاسو په اولادې باندې ډکه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_1.mp3', '', 1761754199, 1761754199),
(51450, 'Genesis 9:2', 'Genesis', 9, 2, 'ټول حیوانات، مرغان، خزندې او ماهیان به ستاسو څخه وېریږي او دا ټول به ستاسو په اختیار کې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_2.mp3', '', 1761754199, 1761754199),
(51451, 'Genesis 9:3', 'Genesis', 9, 3, 'هر شی چې ژوندی دی او حرکت کوي، هغه به ستاسو د خوراک دپاره وي. لکه څنګه چې ما تاسو ته شنه بوټي درکړل، اوس هرڅه تاسو ته درکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_3.mp3', '', 1761754199, 1761754199),
(51452, 'Genesis 9:4', 'Genesis', 9, 4, 'یو شی چې تاسو یې باید ونه خورئ هغه داسې غوښه ده چې وینه په کې وي. دا مې منع کړي دي، ځکه چې په وینه کې ژوندون دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_4.mp3', '', 1761754199, 1761754199),
(51453, 'Genesis 9:5', 'Genesis', 9, 5, 'که څوک د یو انسان څخه ژوند واخلي، هغه به سزا ومومي. که چېرې کوم حیوان یو انسان ووژني، زه به هغه ته د مرګ سزا ورکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_5.mp3', '', 1761754199, 1761754199),
(51454, 'Genesis 9:6', 'Genesis', 9, 6, 'انسان د خدای په شکل جوړ شوی دی، نو چا چې هغه وواژه، هغه به هم د بل چا په وسیله وژل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_6.mp3', '', 1761754199, 1761754199),
(51455, 'Genesis 9:7', 'Genesis', 9, 7, 'تاسو باید زیات ماشومان وزېږوئ، ترڅو ستاسو اولاده په ټوله دنیا کې زیاته شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_7.mp3', '', 1761754199, 1761754199),
(51456, 'Genesis 9:8', 'Genesis', 9, 8, 'خدای نوح او د هغه زامنو ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_8.mp3', '', 1761754199, 1761754199),
(51457, 'Genesis 9:9', 'Genesis', 9, 9, '«زه ستاسو او ستاسو د راتلونکي نسل سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_9.mp3', '', 1761754199, 1761754199),
(51458, 'Genesis 9:10', 'Genesis', 9, 10, 'او ټولو ژوندیو مخلوقاتو سره چې ستاسو سره وو، یعنې مرغانو، کورني او وحشي حیواناتو، هغوی ټول چې تاسو سره د کشتۍ څخه راووتل او همدارنګه د ځمکې په مخ ټولو ژوندیو مخلوقاتو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_10.mp3', '', 1761754199, 1761754199),
(51459, 'Genesis 9:11', 'Genesis', 9, 11, 'لوظ کوم چې بیا به هېڅکله ټول ژوندي مخلوقات د سېلاب په وسیله له منځه نه ځي. هېڅکله به بیا سېلاب ځمکه نه خرابوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_11.mp3', '', 1761754199, 1761754199),
(51460, 'Genesis 9:12', 'Genesis', 9, 12, 'خدای وویل: «دا د هغه لوظ نښه ده چې زما او ستاسو او د هغو ټولو ژوندیو مخلوقاتو ترمنځ به وي چې تاسو سره دي او دا لوظ به د ټول راتلونکي نسل دپاره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_12.mp3', '', 1761754199, 1761754199),
(51461, 'Genesis 9:13', 'Genesis', 9, 13, 'زه د ورېځو په منځ کې د بوډۍ ټال ږدم او دا به زما او د دنیا په منځ کې د لوظ نښه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_13.mp3', '', 1761754199, 1761754199),
(51462, 'Genesis 9:14', 'Genesis', 9, 14, 'کله چې زه په ځمکه باندې ورېځې راخپرې کړم او په هغې کې شنه او سره راښکاره شي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_14.mp3', '', 1761754199, 1761754199),
(51463, 'Genesis 9:15', 'Genesis', 9, 15, 'زه به خپل هغه لوظ چې ستاسو او ټولو ژوندیو مخلوقاتو سره مې کړی ؤ، رایادوم او نور به هېڅکله ټول ژوندي موجودات د سېلاب په وسیله له منځه نه ځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_15.mp3', '', 1761754199, 1761754199),
(51464, 'Genesis 9:16', 'Genesis', 9, 16, 'کله چې په ورېځو کې شنه او سره راښکاره شي، زه به هغې ته ګورم او خپل هغه ابدي لوظ به رایادوم چې زما او د ځمکې په مخ د ټولو ژوندیو مخلوقاتو ترمنځ شوی ؤ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_16.mp3', '', 1761754199, 1761754199),
(51465, 'Genesis 9:17', 'Genesis', 9, 17, 'نو خدای نوح ته وویل: «دا د هغه لوظ نښه ده چې ما د ځان او د ځمکې په مخ د ټولو ژوندیو موجوداتو سره کړی ؤ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_17.mp3', '', 1761754199, 1761754199),
(51466, 'Genesis 9:18', 'Genesis', 9, 18, 'د نوح زامن چې د کشتۍ څخه راووتل هغه سام، حام او یافت وو. وروسته بیا د حام زوی پیدا شو او نوم یې کنعان ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_18.mp3', '', 1761754199, 1761754199),
(51467, 'Genesis 9:19', 'Genesis', 9, 19, 'دا د نوح درې زامن وو چې د هغوی څخه د دنیا ټول خلک راپیدا شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_19.mp3', '', 1761754199, 1761754199),
(51468, 'Genesis 9:20', 'Genesis', 9, 20, 'نوح بزګر ؤ او هغه لومړنی سړی ؤ چې د انګورو باغ یې جوړ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_20.mp3', '', 1761754199, 1761754199),
(51469, 'Genesis 9:21', 'Genesis', 9, 21, 'یوه ورځ هغه شراب وڅښل او نشه شو، خپل کالي یې وویستل او په خپله خېمه کې لوڅ پرېوت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_21.mp3', '', 1761754199, 1761754199),
(51470, 'Genesis 9:22', 'Genesis', 9, 22, 'حام خېمې ته ننوت او ویې لیدل چې هغه لوڅ دی، نو هغه دباندې راووت او خپلو ورونو ته یې هم وویل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_22.mp3', '', 1761754199, 1761754199),
(51471, 'Genesis 9:23', 'Genesis', 9, 23, 'بیا سام او یافت چپنه واخیستله او په خپلو اوږو باندې یې واچوله. هغوی په شا باندې خېمې ته ورغلل، خپل پلار یې ورباندې پټ کړ او خپل مخونه یې بلې خواته واړول، ترڅو د خپل پلار لوڅوالی ونه ویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_23.mp3', '', 1761754199, 1761754199),
(51472, 'Genesis 9:24', 'Genesis', 9, 24, 'کله چې نوح د نشې څخه په حال شو، په دې پوه شو چې د هغه کشر زوی د هغه سره څه کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_24.mp3', '', 1761754199, 1761754199),
(51473, 'Genesis 9:25', 'Genesis', 9, 25, 'هغه وویل: وي دې لعنت په کنعان باندې هغه به وي د خپلو ورونو غلام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_25.mp3', '', 1761754199, 1761754199),
(51474, 'Genesis 9:26', 'Genesis', 9, 26, 'د سام څښتن خدای ته ثنا ووایئ! کنعان به وي د سام غلام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis9_verse_26.mp3', '', 1761754199, 1761754199),
