(51494, 'Lamentations 3:17', 'Lamentations', 3, 17, 'زما زړۀ د سلامتيا نه خالى شوے دے او ما نه هېر دى چې خوشحالى څۀ ته وائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_17.mp3', '', 1761754199, 1761754199),
(51495, 'Lamentations 3:18', 'Lamentations', 3, 18, 'نو زۀ دا وايم، ”زما طمع او اُميد لاړو او څۀ چې زما د مالِک خُدائ نه اُميد وو هغه ختم شو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_18.mp3', '', 1761754199, 1761754199),
