(51500, 'Lamentations 3:23', 'Lamentations', 3, 23, 'د هغۀ رحم او مينه هر سحر نوے او تازه کيږى او د هغۀ وفادارى بې‌شانه لويه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_23.mp3', '', 1761754199, 1761754199),
(51501, 'Lamentations 3:24', 'Lamentations', 3, 24, '”مالِک خُدائ زما نصيب دے،“ او زۀ خپل ځان ته دا وايم، ”نو په دې وجه زۀ به د هغۀ نه اُميد ساتم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_24.mp3', '', 1761754199, 1761754199),
(51502, 'Lamentations 3:25', 'Lamentations', 3, 25, 'مالِک خُدائ هغه چا سره ښۀ دے څوک چې په هغۀ باور کوى او هغه کس څوک چې د هغۀ تلاش کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_25.mp3', '', 1761754199, 1761754199),
(51503, 'Lamentations 3:26', 'Lamentations', 3, 26, 'دا ښۀ ده چې يو کس په خاموشۍ سره انتظار وکړى، د مالِک خُدائ خلاصون ته انتظار وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_26.mp3', '', 1761754199, 1761754199),
(51504, 'Lamentations 3:27', 'Lamentations', 3, 27, 'د يو کس دپاره دا ښۀ ده چې په ځوانۍ کښې جغ يوسى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_27.mp3', '', 1761754199, 1761754199),
(51505, 'Lamentations 3:28', 'Lamentations', 3, 28, 'چې په خاموشۍ کښې ځان له کښېنى، څۀ چې مالِک خُدائ پرې اېښے وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_28.mp3', '', 1761754199, 1761754199),
(51506, 'Lamentations 3:29', 'Lamentations', 3, 29, 'هغه دې خپل ځان پړمخې په خاورو کښې وغورزوى، کېدے شى چې څۀ اُميد پاتې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_29.mp3', '', 1761754199, 1761754199),
(51507, 'Lamentations 3:30', 'Lamentations', 3, 30, 'ظالم ته دې د وهلو دپاره خپل مخ ورواړوى او د هغۀ د لاسه دې بې‌عزتى قبوله کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_30.mp3', '', 1761754199, 1761754199),
(51508, 'Lamentations 3:31', 'Lamentations', 3, 31, 'ځکه مالِک به انسان د تل دپاره نۀ رد کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_31.mp3', '', 1761754199, 1761754199),
(51509, 'Lamentations 3:32', 'Lamentations', 3, 32, 'دا کۀ هغه غم راولى، هغه به رحم هم کوى، د هغه مينې په مطابق چې ډېره او پائيداره ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_32.mp3', '', 1761754199, 1761754199),
(51510, 'Lamentations 3:33', 'Lamentations', 3, 33, 'هغه چا ته په تکليف رسولو نۀ خوشحاليږى او نۀ څوک په غم آخته کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_33.mp3', '', 1761754199, 1761754199);